const userName = 'global user';

function loadPage() {
  const userName = 'page user';   // shadows the global — nearest wins
  function render() {
    const role = 'dev';           // visible only inside render
    return userName + ' / ' + role; // found one scope out
  }
  console.log(render());          // "page user / dev"
  try { console.log(role); } catch (e) { console.log(e.name); } // "ReferenceError"
}

loadPage();
console.log(userName);            // "global user" — untouched by the shadow

function processOrder(order) {
  if (order.paid) {
    var status = 'paid';            // function-scoped: belongs to processOrder
    const receipt = 'R-' + order.id; // block-scoped: belongs to the if block
    console.log(status, receipt);    // "paid R-7"
  }
  console.log(status);              // "paid" — var escaped the block
  try { console.log(receipt); } catch (e) { console.log(e.name); } // "ReferenceError"
}

processOrder({ paid: true, id: 7 });

function makeGreeter(name) {
  return function greet() {
    return 'hi, ' + name;   // name belongs to a call that is OVER
  };
}

const hiAda = makeGreeter('Ada');
console.log(hiAda());        // "hi, Ada"

function multiplyBy(factor) {
  return (n) => n * factor; // same mechanism, arrow flavor
}
const triple = multiplyBy(3);
console.log(triple(7));      // 21

function makeScore() {
  let score = 0;                  // ONE binding…
  function bump() { score += 10; }  // …written by this closure
  function read() { return score; } // …read by this closure
  return { bump, read };
}

const game = makeScore();
game.bump();
game.bump();
console.log(game.read());        // 20 — bump's writes are visible to read

const varFns = [];
for (var i = 0; i < 3; i++) varFns.push(() => i);

const letFns = [];
for (let j = 0; j < 3; j++) letFns.push(() => j);

const iifeFns = [];                       // the pre-2015 fix
for (var k = 0; k < 3; k++) {
  (function (copy) { iifeFns.push(() => copy); })(k);
}

console.log(varFns.map((f) => f()));   // [3, 3, 3] — one shared i
console.log(letFns.map((f) => f()));   // [0, 1, 2] — a fresh j per iteration
console.log(iifeFns.map((f) => f()));  // [0, 1, 2] — a fresh copy per call
console.log(i);                         // 3 — the shared binding is still right here

function makeWallet(openingBalance) {
  let balance = openingBalance;   // private: no property, no global

  return {
    deposit(amount) { balance += amount; return balance; },
    spend(amount) {
      if (amount > balance) return 'declined: only ' + balance + ' left';
      balance -= amount;
      return balance;
    },
    getBalance() { return balance; },
  };
}

const wallet = makeWallet(100);
console.log(wallet.deposit(50));   // 150
console.log(wallet.spend(30));     // 120
console.log(wallet.spend(1000));   // "declined: only 120 left"
console.log(wallet.getBalance());  // 120
console.log(wallet.balance);       // undefined — there is no such property

const studyStats = (function () {
  let total = 0;      // private
  let sessions = 0;   // private

  function add(minutes) {   // private helper
    total += minutes;
    sessions += 1;
  }

  return {                  // the public API — everything else stays hidden
    study(minutes) { add(minutes); return total; },
    average() { return sessions === 0 ? 0 : total / sessions; },
  };
})();

studyStats.study(30);
studyStats.study(45);
console.log(studyStats.average());  // 37.5
console.log(studyStats.total);      // undefined — not part of the API

// studyStats.js — a module: file scope + explicit exports
let total = 0;
let sessions = 0;

export function study(minutes) {   // public — importable by name
  total += minutes;
  sessions += 1;
  return total;
}

export function average() {
  return sessions === 0 ? 0 : total / sessions;
}

