function makeSeen() {
  const seenIds = new Set();      // private memory — captured, not exposed
  return function seen(id) {
    const firstTime = !seenIds.has(id);
    if (firstTime) seenIds.add(id);
    return firstTime;
  };
}

const seen = makeSeen();
console.log('deduped: ' + [101, 102, 101, 103, 102, 101, 104].filter((id) => seen(id)));
// deduped: 101,102,103,104 — first occurrences only

console.log('memory from outside: ' + seen.seenIds); // undefined — private

const fresh = makeSeen(); // a brand-new, empty memory
console.log('independent: ' + [101, 101, 105].filter((id) => fresh(id)));
// independent: 101,105

